    private fun setProfileImage(imageView: ImageView) {
        if (!isAdded) return

        showLoading()
        val authId = mAuth?.currentUserOrNull()?.id ?: return hideLoading()

        val cachedUrl: String? = PayorAdapter.sDownloadUrlCache[authId]

        if (cachedUrl != null) {
            loadGlideProfileImage(imageView, cachedUrl)
        } else {
            lifecycleScope.launch {
                try {
                    val user = withContext(Dispatchers.IO) {
                        DeclareDatabase.usersTable.select(Columns.list("user_id", "profile_image_url")) {
                            filter { eq("auth_id", authId) }
                        }.decodeSingleOrNull<User>()
                    }

                    val numericUserId = user?.id
                    val url = user?.profileImageUrl ?: if (numericUserId != null) {
                        DeclareDatabase.profileImagesBucket.publicUrl("$numericUserId/$numericUserId.jpg")
                    } else {
                        null
                    }

                    if (url != null) {
                        PayorAdapter.sDownloadUrlCache[authId] = url
                        loadGlideProfileImage(imageView, url)
                    } else {
                        withContext(Dispatchers.Main) {
                            imageView.setImageResource(R.drawable.placeholder_profile_image)
                            hideLoading()
                        }
                    }
                } catch (e: Exception) {
                    withContext(Dispatchers.Main) {
                        imageView.setImageResource(R.drawable.placeholder_profile_image)
                        hideLoading()
                    }
                }
            }
        }
    }

    private fun loadGlideProfileImage(imageView: ImageView, url: String?) {
        if (!isAdded) {
            hideLoading()
            return
        }

        Glide.with(this)
            .load(url)
            .placeholder(R.drawable.placeholder_profile_image)
            .diskCacheStrategy(DiskCacheStrategy.ALL)
            .signature(ObjectKey(imageSignature))
            .listener(object : RequestListener<Drawable?> {
                override fun onLoadFailed(
                    e: GlideException?,
                    model: Any?,
                    target: Target<Drawable?>?,
                    isFirstResource: Boolean
                ): Boolean {
                    hideLoading()
                    return false
                }

                override fun onResourceReady(
                    resource: Drawable?,
                    model: Any?,
                    target: Target<Drawable?>?,
                    dataSource: DataSource?,
                    isFirstResource: Boolean
                ): Boolean {
                    hideLoading()
                    return false
                }
            })
            .into(imageView)
    }

    private fun setupEditNickname() {
        editNickname?.setOnClickListener {
            switchToEditMode()
            nicknameEditText?.requestFocus()
            val imm = requireContext().getSystemService(Context.INPUT_METHOD_SERVICE) as InputMethodManager
            imm.showSoftInput(nicknameEditText, InputMethodManager.SHOW_IMPLICIT)
        }
    }

    private fun setupSaveNickname() {
        saveNickname?.setOnClickListener {
            saveNicknameAndSwitchMode()
            val imm = requireContext().getSystemService(Context.INPUT_METHOD_SERVICE) as InputMethodManager
            imm.hideSoftInputFromWindow(nicknameEditText?.windowToken, 0)
        }
    }

    private fun loadNicknameAndData() {
        showLoading()
        val currentUserId = mAuth?.currentUserOrNull()?.id ?: return hideLoading()
        lifecycleScope.launch {
            try {
                val user = withContext(Dispatchers.IO) {
                    DeclareDatabase.usersTable.select(Columns.list("username")) {
                        filter { eq("auth_id", currentUserId) }
                    }.decodeSingleOrNull<User>()
                }
                currentNickname = user?.username ?: ""
                nicknameTextView?.text = currentNickname

                totalBalanceUnpaid()
                fetchDebt()
                fetchOwe()
            } catch (e: Exception) {
                Log.e("Supabase", "Error loading profile data: ${e.message}")
            } finally {
                hideLoading()
            }
        }
    }

    private fun switchToEditMode() {
        nicknameTextView?.visibility = View.GONE
        nicknameEditText?.visibility = View.VISIBLE
        nicknameEditText?.setText(currentNickname)
        editNickname?.visibility = View.GONE
        saveNickname?.visibility = View.VISIBLE
    }

    private fun switchToDisplayMode() {
        nicknameTextView?.visibility = View.VISIBLE
        nicknameEditText?.visibility = View.GONE
        nicknameTextView?.text = currentNickname
        editNickname?.visibility = View.VISIBLE
        saveNickname?.visibility = View.GONE
    }

    private fun saveNicknameAndSwitchMode() {
        val updatedNickname = nicknameEditText?.text.toString().trim()
        if (updatedNickname.isEmpty()) {
            Toast.makeText(requireContext(), "Nickname cannot be empty", Toast.LENGTH_SHORT).show()
            return
        }

        val currentUserId = mAuth?.currentUserOrNull()?.id ?: return
        showLoading()
        lifecycleScope.launch {
            try {
                // Check if username already exists
                Log.d("Supabase", "Checking if username '$updatedNickname' exists...")
                val existingUser = withContext(Dispatchers.IO) {
                    DeclareDatabase.usersTable.select(Columns.list("user_id")) {
                        filter { 
                            eq("username", updatedNickname)
                            neq("auth_id", currentUserId)
                        }
                    }.decodeSingleOrNull<User>()
                }

                if (existingUser != null) {
                    Toast.makeText(requireContext(), "Username already taken", Toast.LENGTH_SHORT).show()
                    hideLoading()
                    return@launch
                }

                val updateData = buildJsonObject {
                    put("username", updatedNickname)
                }

                withContext(Dispatchers.IO) {
                    // Update the 'users' table in Postgrest
                    DeclareDatabase.usersTable.update(updateData) {
                        filter { eq("auth_id", currentUserId) }
                    }

                    // Sync with Supabase Auth Metadata (Display Name)
                    mAuth?.updateUser {
                        data = buildJsonObject {
                            put("display_name", updatedNickname)
                        }
                    }

                    // Update cache
                    val user = DeclareDatabase.usersTable.select(Columns.list("user_id")) {
                        filter { eq("auth_id", currentUserId) }
                    }.decodeSingleOrNull<User>()
                    user?.id?.let { UserHelper.updateCache(it, updatedNickname) }
                }

                currentNickname = updatedNickname
                switchToDisplayMode()

                // Sync with MainActivity
                (activity as? MainActivity)?.currentNickname = currentNickname

                totalBalanceUnpaid() // Re-calculate based on new nickname if needed
                Toast.makeText(requireContext(), "Profile updated", Toast.LENGTH_SHORT).show()
            } catch (e: Exception) {
                Log.e("Supabase", "Error saving nickname: ${e.message}", e)
                Toast.makeText(requireContext(), "Failed to update profile: ${e.message}", Toast.LENGTH_LONG).show()
            } finally {
                hideLoading()
            }
        }
    }

    private fun fetchOwe() {
        val currentUserId = mAuth?.currentUserOrNull()?.id ?: return
        showLoading()
        lifecycleScope.launch {
            try {
                val user = withContext(Dispatchers.IO) {
                    DeclareDatabase.usersTable.select(Columns.list("user_id")) {
                        filter { eq("auth_id", currentUserId) }
                    }.decodeSingleOrNull<User>()
                }

                if (user?.id != null) {
                    val borrows = withContext(Dispatchers.IO) {
                        DeclareDatabase.borrowsTable.select {
                            filter { 
                                eq("lender_id", user.id)
                                neq("status", 3) // Not Paid
                            }
                        }.decodeList<BorrowNowTransaction>()
                    }
                    currentOwe = borrows.sumOf { it.borrowedAmount ?: 0.0 }
                }
            } catch (e: Exception) {
                Log.e("Supabase", "Error fetching owe: ${e.message}")
            } finally {
                hideLoading()
            }
        }
    }

    private fun fetchDebt() {
        val currentUserId = mAuth?.currentUserOrNull()?.id ?: return
        showLoading()
        lifecycleScope.launch {
            try {
                val user = withContext(Dispatchers.IO) {
                    DeclareDatabase.usersTable.select(Columns.list("user_id")) {
                        filter { eq("auth_id", currentUserId) }
                    }.decodeSingleOrNull<User>()
                }

                if (user?.id != null) {
